def preencher_cancelamentos(apps, schema_editor):
    """Contas já canceladas: a data é a da última alteração e o motivo vem das observações ("[CANCELADA] … em …")."""
    import re
    ContaMesa = apps.get_model('pos', 'ContaMesa')
    padrao = re.compile(r'\[CANCELADA\] (.*) em \d{4}-\d{2}-\d{2}')
    for c in ContaMesa.objects.filter(status='cancelada', cancelada_em__isnull=True).only('id', 'atualizada_em', 'observacoes'):
        m = padrao.findall(c.observacoes or '')
        ContaMesa.objects.filter(id=c.id).update(cancelada_em=c.atualizada_em, motivo_cancelamento=(m[-1] if m else '')[:300])
    # contas abertas pela conta principal: o nome do dono (as dos membros nunca foram registadas)
    for c in ContaMesa.objects.filter(atendente__isnull=False, atendente_nome='').select_related('atendente__user'):
        u = c.atendente.user
        nome = (f'{u.first_name} {u.last_name}'.strip() or u.username)[:100]
        ContaMesa.objects.filter(id=c.id).update(atendente_nome=nome)


